WITH filtered AS (SELECT *, CASE WHEN device = 'desktop' THEN 1 ELSE 0 END AS is_desktop, HOUR(started_at) AS started_at_hour FROM sessions WHERE country IS NOT NULL AND browser IS NOT DISTINCT FROM 'Safari'), with_gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY country ORDER BY started_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_burst FROM filtered), sessionized AS (SELECT id, customer_id, device, started_at, country, is_desktop, started_at_hour, SUM(is_new_burst) OVER (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT CASE WHEN is_desktop >= 65 THEN 'LARGE' ELSE 'SMALL' END AS is_desktop_tier, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS duration_min, SUM(started_at_hour) AS total_started_at_hour, COUNT_IF(device = 'desktop') AS desktop_events FROM sessionized GROUP BY CASE WHEN is_desktop >= 65 THEN 'LARGE' ELSE 'SMALL' END HAVING total_started_at_hour > 0
